urlset:


  {{ base_url }}/



  {{ base_url }}/writing



  {{ base_url }}/research



  {{ base_url }}/experiments



  {{ base_url }}/projects



  {{ base_url }}/books



  {{ base_url }}/courses



{% for item in posts %}

  {{ base_url }}/{{ item.type }}/{{ item.slug }}

  {% if item.updated_at or item.published_at %}
  {{ (item.updated_at or item.published_at).strftime('%Y-%m-%d') }}
  {% endif %}


{% endfor %}


{% for course in courses %}

  {{ base_url }}/courses/{{ course.slug }}
  {% if course.updated_at or course.created_at %}
  {{ (course.updated_at or course.created_at).strftime('%Y-%m-%d') }}
  {% endif %}

{% endfor %}
